Here's a complete example of data-driven MSTest tests for a `PriceCalculator` class:

```csharp
// PriceCalculator.cs
public class PriceCalculator
{
    public decimal CalculateTotal(decimal unitPrice, int quantity)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(unitPrice);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);
        return unitPrice * quantity;
    }

    public decimal ApplyDiscount(decimal total, decimal discountPercent)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(total);
        if (discountPercent is < 0 or > 100)
            throw new ArgumentOutOfRangeException(nameof(discountPercent));
        return total * (1 - discountPercent / 100m);
    }
}
```

```csharp
// PriceCalculatorTests.cs
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- DataRow: inline test cases ---

    [TestMethod]
    [DataRow(10.00, 1, 10.00)]
    [DataRow(10.00, 3, 30.00)]
    [DataRow(0.99, 5, 4.95)]
    [DataRow(0.00, 2, 0.00)]
    public void CalculateTotal_ValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.0, 100.00)]
    [DataRow(100.00, 10.0, 90.00)]
    [DataRow(100.00, 50.0, 50.00)]
    [DataRow(100.00, 100.0, 0.00)]
    [DataRow(249.99, 20.0, 199.992)]
    public void ApplyDiscount_ValidInputs_ReturnsExpected(
        double total, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)total, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: complex/reusable test cases ---

    [TestMethod]
    [DynamicData(nameof(BulkOrderCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_BulkOrders_ReturnsExpected(
        decimal unitPrice, int quantity, decimal expected)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity);

        Assert.AreEqual(expected, result);
    }

    private static IEnumerable<object[]> BulkOrderCases()
    {
        yield return new object[] { 5.50m, 100, 550.00m };
        yield return new object[] { 19.99m, 50, 999.50m };
        yield return new object[] { 0.01m, 1000, 10.00m };
    }

    // --- DynamicData with display name ---

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method,
        DynamicDataDisplayName = nameof(FormatDiscountCase))]
    public void ApplyDiscount_InvalidPercent_Throws(
        decimal total, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(total, discountPercent));
    }

    private static IEnumerable<object[]> InvalidDiscountCases()
    {
        yield return new object[] { 100m, -1m };
        yield return new object[] { 100m, 101m };
        yield return new object[] { 50m, -0.01m };
    }

    public static string FormatDiscountCase(MethodInfo _, object[] data)
        => $"Total={data[0]}, Discount={data[1]}%";

    // --- Negative cases for CalculateTotal ---

    [TestMethod]
    [DataRow(-1.00, 1)]
    public void CalculateTotal_NegativePrice_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }

    [TestMethod]
    [DataRow(10.00, 0)]
    [DataRow(10.00, -1)]
    public void CalculateTotal_InvalidQuantity_Throws(double unitPrice, int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity));
    }
}
```

**Key best practices shown:**

| Technique | When to use |
|-----------|-------------|
| `[DataRow]` | Simple inline values (note: `decimal` isn't allowed, use `double` and cast) |
| `[DynamicData]` with method | Complex types, `decimal` literals, or shared/generated data |
| `DynamicDataDisplayName` | Custom test names in Test Explorer |

**Other tips:**
- One assertion per test method — each `[DataRow]` runs as an independent test case
- Use `ThrowsException` for negative cases rather than `ExpectedException` (deprecated pattern)
- Name tests: `Method_Scenario_ExpectedBehavior`
- `DynamicDataSourceType.Method` (preferred) vs `.Property` — methods support lazy generation
